:root { --accent: #5f3dc4; --text: #212529; --muted: #868e96; }
* { box-sizing: border-box; }
body { margin: 0; font-family: system-ui, sans-serif; color: var(--text); background: #fafafa; }
main { max-width: 720px; margin: 0 auto; padding: 40px 20px; }
h1 { margin: 0; }
.tagline { color: var(--muted); }
.panes { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; margin: 28px 0; }
section { background: #fff; border: 1px solid #e9ecef; border-radius: 12px; padding: 20px; }
button, .fake-btn {
  font: inherit; padding: 10px 18px; border-radius: 8px; cursor: pointer;
  border: 1px solid #ced4da; background: #fff;
}
button.primary, .fake-btn.primary { background: var(--accent); color: #fff; border-color: var(--accent); }
button:focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; }

/* Broken modal styling — looks identical, behaves terribly */
.overlay { position: fixed; inset: 0; background: rgb(0 0 0 / .5); display: grid; place-items: center; }
.modal { background: #fff; border-radius: 12px; padding: 24px; width: min(380px, 90vw); }
.fake-btn { display: inline-block; user-select: none; }
.actions { display: flex; gap: 10px; justify-content: flex-end; margin-top: 16px; }

/* Fixed modal */
dialog { border: none; border-radius: 12px; padding: 24px; width: min(380px, 90vw); }
dialog::backdrop { background: rgb(0 0 0 / .5); }
dialog input { width: 100%; padding: 10px 12px; margin-top: 4px; border: 1.5px solid #ced4da; border-radius: 8px; font: inherit; }
dialog label { font-size: .9rem; font-weight: 600; }
body:has(dialog[open]) { overflow: hidden; } /* scroll lock */

// modal-rescue — the fixed side.
// The broken side is wired inline in the HTML on purpose, defects and all.

const openFixed = document.getElementById("open-fixed");
const dialog = document.getElementById("fixed-modal");

// The broken opener: just flips display. No focus move, no trap, no Escape.
document.getElementById("open-broken").addEventListener("click", () => {
  document.getElementById("broken-modal").style.display = "grid";
});

// The fixed opener: showModal() gives us focus trapping, Escape handling,
// aria-modal semantics, and ::backdrop — all from the platform.
openFixed.addEventListener("click", () => {
  dialog.showModal();
});

// Focus restoration: when the dialog closes (any way — Escape, button),
// return focus to the control that opened it. `close` fires for all paths.
dialog.addEventListener("close", () => {
  openFixed.focus();
});

document.getElementById("fixed-close").addEventListener("click", () => dialog.close());
document.getElementById("fixed-subscribe").addEventListener("click", () => {
  // Real apps would validate + submit here.
  dialog.close("subscribed");
});

// Light-dismiss: clicking the backdrop closes. The dialog element itself
// receives the click when the backdrop is hit, so we check the target.
dialog.addEventListener("click", (e) => {
  if (e.target === dialog) dialog.close();
});

issue.body:
Great first a11y contribution! Add a subtle open animation to the fixed dialog (e.g. fade + slight scale via `@keyframes` on `dialog[open]`), then wrap it so users with motion sensitivity get an instant, animation-free open:

```css
@media (prefers-reduced-motion: reduce) {
  dialog[open] { animation: none; }
}
```

Acceptance: animation plays normally, and with reduced motion enabled in OS settings (or emulated in DevTools → Rendering), the dialog appears instantly. Bonus points for adding a line to AUDIT.md about it. Under an hour — comment to claim!
